<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import GameWindow from '../components/GameWindow.vue';
import GameSwitch from '../components/GameSwitch.vue';
import GameArt from '../components/GameArt.vue';
import { state, action, request, walletOperation, openScreen, setPreference, setLocale, refreshInvites } from '../services/game-store';
import { syncMusic } from '../platform/audio';
import { ageBand, allowAds, revokeAds, canShowAds, ensureResourceAge } from '../platform/audience';
const t = (ru: string, en: string) => state.locale === 'ru' ? ru : en;
const nickname = ref(state.profile!.nickname), rules = ref(state.profile!.communityRulesVersion === 1);
const p = computed(() => state.profile!), w = computed(() => p.value.wallet);
const band = ageBand();
const adsAllowed = ref(canShowAds());
const inviterCode=ref('');
onMounted(()=>{void action(refreshInvites);});
const applyInviter=()=>action(async()=>{if(!await ensureResourceAge())return;await request({action:'invites_bind',code:inviterCode.value});await refreshInvites();if(state.invites?.inviterAssigned)inviterCode.value='';});
function toggleAds() { adsAllowed.value ? revokeAds() : allowAds(); adsAllowed.value = canShowAds(); }
async function saveName() { if (rules.value && p.value.communityRulesVersion !== 1) await request({ action: 'public_rules_accept', version: 1 }); await request({ action: 'rename', nickname: nickname.value, communityRulesVersion: 1 }); state.notice = t('Имя сохранено','Name saved'); }
const openRanking = (tab: string) => { state.rankingTab = tab; state.period='all';openScreen('ranking', 'profile'); };
function copyId() { void navigator.clipboard.writeText(p.value.id).then(() => state.notice = t('Скопировано','Copied')).catch(() => state.error = t('Не удалось скопировать','Could not copy')); }
const resetNames = () => action(async()=>{await request({action:'public_names_reset'});state.notice=t('Скрытые имена сброшены','Hidden names reset');});
</script>
<template>
  <GameWindow :title="t('Аккаунт','Account')" tall class="profile-window">
    <section class="account-hero"><GameArt class="account-portrait" src="/assets/branding/ui/hud-player-portrait-v1.png"/><div><label class="nickname-label" for="nickname">{{ t('Игровой ник','Game nickname') }} <small>{{ t('2–24 символа','2–24 characters') }}</small></label><span class="copy-line"><input id="nickname" v-model="nickname" minlength="2" maxlength="24" :disabled="state.busy" @keydown.enter="!state.busy&&rules&&nickname.trim()!==p.nickname&&action(saveName)"><button class="primary nickname-save" :aria-label="t('Сохранить имя','Save name')" :disabled="state.busy||!rules||nickname.trim()===p.nickname||nickname.trim().length<2" @click="action(saveName)">✓</button></span></div></section>
    <label v-if="p.communityRulesVersion!==1||nickname.trim()!==p.nickname" class="check-row name-rules"><input v-model="rules" type="checkbox">{{ t('Принимаю правила сообщества: без оскорблений, чужих данных и выдачи себя за другого.','I accept the community rules: no offensive names, personal information or impersonation.') }}</label>
    <div class="stat-grid"><button class="stat-card" @click="openRanking('record')"><small>{{ t('Рекорд','Best') }} ›</small><strong>{{ w.bestTimeMs>0?`${(w.bestTimeMs/1000).toFixed(3)} ${t('с','s')}`:'—' }}</strong></button><button class="stat-card" @click="openRanking('average')"><small>{{ t('Среднее','Average') }} ›</small><strong>{{ state.average?.mine.averageMs == null?'—':`${(state.average.mine.averageMs/1000).toFixed(3)} ${t('с','s')}` }}</strong></button><button class="stat-card" @click="openScreen('history','profile')"><small>{{ t('Попыток','Attempts') }} ›</small><strong>{{ state.average?.mine.totalAttempts??state.history.filter(a=>a.phase==='confirmed').length }}</strong></button></div>
    <section class="blue-panel telegram-identity"><div class="identity-heading"><GameArt class="identity-cloud" src="/assets/branding/account/cloud-v1.png"/><div><h2>{{ t('Telegram подключён','Telegram connected') }}</h2><small>{{ p.telegramUsername ? `@${p.telegramUsername}` : t('Прогресс сохраняется в облаке','Progress is saved in the cloud') }}</small></div><span class="connected-check">✓</span></div><button v-if="!w.claimed.includes('energy_telegram')" class="secondary full" :disabled="state.busy" @click="action(async()=>{if(await ensureResourceAge())await walletOperation('energy_reward',{id:'telegram'});})">{{ t('Забрать награду за вход','Collect sign-in reward') }} +{{ w.energyConfig.rewards.google }} ϟ</button><label class="setting-row privacy-setting"><GameArt class="setting-icon" src="/assets/branding/account/eye.svg"/><span><strong>{{ t('Скрывать Telegram username','Hide Telegram username') }}</strong><small>{{ t('В рейтинге виден ваш игровой ник.','Your game nickname is visible on the leaderboard.') }}</small></span><GameSwitch :model-value="p.hideTelegramAccount" :disabled="state.busy" @update:model-value="action(()=>walletOperation('telegram_privacy',{hide:$event}))"/></label></section>
    <button class="menu-row" @click="openScreen('age','profile')"><strong>{{ t('Возраст','Age') }}</strong><span>{{ band==='adult18plus'?'18+':band==='under18'?t('До 18 лет','Under 18'):t('Не указан','Not specified') }}</span><i>›</i></button>
    <button v-if="p.hiddenPlayers.length" class="menu-row" :disabled="state.busy" @click="resetNames"><GameArt class="setting-icon" src="/assets/branding/account/eye.svg"/><strong>{{t('Скрытые имена','Hidden names')}}: {{p.hiddenPlayers.length}}</strong><small>{{t('Сбросить','Reset')}}</small></button>
    <label v-if="band==='adult18plus'&&state.platform?.ads.enabled" class="setting-row"><span><strong>{{ t('Реклама между попытками','Ads between runs') }}</strong><small>{{ t('Разрешить на эту сессию. Можно выключить в любой момент.','Allow for this session. You can turn it off at any time.') }}</small></span><GameSwitch :model-value="adsAllowed" @update:model-value="toggleAds"/></label>
    <div class="audio-settings"><label v-for="key in (['sound','music'] as const)" :key="key" class="blue-panel audio-setting"><GameArt class="setting-icon" :src="`/assets/branding/account/${key}.svg`"/><span>{{ key==='sound'?t('Звуки','Sounds'):t('Музыка','Music') }}</span><GameSwitch :model-value="state.preferences[key]" @update:model-value="setPreference(key,$event);syncMusic()"/></label></div>
    <details class="blue-panel extra-settings"><summary>{{ t('Язык и вибрация','Language and vibration') }}</summary><label class="setting-row"><span>{{ t('Вибрация','Vibration') }}</span><GameSwitch :model-value="state.preferences.vibration" @update:model-value="setPreference('vibration',$event)"/></label><label class="setting-row"><span>{{ t('Язык','Language') }}</span><select :value="state.locale" @change="setLocale(($event.target as HTMLSelectElement).value)"><option value="ru">Русский</option><option value="en">English</option></select></label></details>
    <section class="blue-panel profile-inviter"><label class="field-label">{{t('Код пригласившего','Inviter code')}}<span class="copy-line"><input v-model="inviterCode" :placeholder="state.invites?.inviterCode??t('Введите код','Enter code')" :disabled="state.busy||state.invites?.inviterAssigned||!state.invites" maxlength="12"><button v-if="!state.invites?.inviterAssigned" class="primary nickname-save" :aria-label="t('Применить код','Apply code')" :disabled="state.busy||!state.invites||!inviterCode.trim()" @click="applyInviter">✓</button><button class="icon-button" :aria-label="t('Информация о приглашении','Invitation details')" @click="openScreen('friends','profile')">ⓘ</button></span></label></section>
    <button class="menu-row" @click="openScreen('help','profile')"><img src="/assets/branding/account/help.svg" alt=""><strong>{{ t('Помощь и приватность','Help and privacy') }}</strong><i>›</i></button>
    <p class="profile-id">ID: {{ p.id }} <button class="text-button" @click="copyId">{{ t('Копировать','Copy') }}</button></p>
    <p v-if="state.error" class="error-message" role="alert">{{ state.error }}</p>
  </GameWindow>
</template>
